#include "CompletionReadinessTask.hpp"
#include <iostream>
using namespace udm;
template<class F>static bool until(F test){const auto end=GetTickCount64()+5000;while(!test()&&GetTickCount64()<end)Sleep(1);return test();}
struct ReadinessWriter {std::promise<void> release;std::thread thread;std::atomic_bool held=false;bool opened=false;explicit ReadinessWriter(Manager& manager){auto gate=release.get_future().share();thread=std::thread([this,&manager,gate]{Lock lock(manager.mutex);held=true;gate.wait();});if(!until([&]{return held.load();}))throw std::runtime_error("Writer deadline");}void open(){if(!opened){opened=true;release.set_value();}if(thread.joinable())thread.join();}~ReadinessWriter(){open();}};
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;auto check=[&](bool ok,const char* label){checks.push_back({{"name",label},{"passed",ok}});if(!ok)throw std::runtime_error(label);};
 try{Manager manager(root/L"state");manager.save();auto before=manager.snapshot();auto disk=readText(manager.root/L"state.json");CompletionReadinessTask task;
  {ReadinessWriter writer(manager);std::atomic_bool waiting=false;task.start(manager,{},[&](const char* stage){if(std::string(stage)=="waiting-model")waiting=true;});check(until([&]{return waiting.load();})&&writer.held&&!task.ready(),"Waiting for the model does not block admission's caller");bool rejected=false;try{task.start(manager);}catch(...){rejected=true;}check(rejected&&task.valid(),"Duplicate start preserves the original readiness operation");check(task.finish().cancelled&&writer.held&&!task.valid(),"Cancelling joins before a held model writer releases");writer.open();}
  manager.fileInfoDecisionPending=true;std::atomic_bool waiting=false;task.start(manager,{},[&](const char* stage){if(std::string(stage)=="waiting-model")waiting=true;});check(until([&]{return waiting.load();})&&!task.ready(),"Availability waits for an accepted model decision");check(task.finish().cancelled&&manager.fileInfoDecisionPending,"Read cancellation does not release another owner's decision");manager.fileInfoDecisionPending=false;
  std::atomic_bool notified=false;bool unlocked=false;task.start(manager,[&]{notified=true;throw std::runtime_error("Ignored wake failure");},[&](const char* stage){if(std::string(stage)=="available"){std::thread probe([&]{std::unique_lock lock(manager.mutex,std::try_to_lock);unlocked=lock.owns_lock();});probe.join();}});check(until([&]{return notified.load();})&&task.ready(),"A wake-up failure cannot discard an available result");auto result=task.take();check(!result.cancelled&&result.error.empty()&&unlocked&&!task.valid(),"Available result is published after model unlock and joined on acknowledgement");
  task.start(manager,{},[](const char* stage){if(std::string(stage)=="available")throw std::runtime_error("Owned availability failure");});check(until([&]{return task.ready();}),"An availability exception reaches a terminal result");result=task.take();check(result.error=="Owned availability failure"&&!task.valid(),"An availability failure is reported and consumed for retry");task.start(manager);check(until([&]{return task.ready();})&&task.take().error.empty(),"A failed preparation permits a fresh readiness request");
  {ReadinessWriter writer(manager);task.start(manager);writer.open();check(until([&]{return task.ready();})&&!task.take().cancelled,"Releasing the actual model writer produces readiness without a UI timer wait");}
  task.finish();task.finish();check(!task.valid()&&!manager.fileInfoDecisionPending,"Repeated readiness cleanup is safe and owns no decision guard");check(manager.snapshot()==before&&readText(manager.root/L"state.json")==disk,"Readiness neither consumes completion actions nor changes the model or catalog");manager.stop();
 }catch(const std::exception& problem){error=problem.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;}
